type Frame = { uri: string; width: number; height: number };

const decoded = new Map<string, string>();

export const getDecoded = (uri: string): string | undefined => decoded.get(uri);

export function useScannerFrames(camera: Camera): Frame | null {
  const [last, setLast] = useState<Frame | null>(null);

  useEffect(() => {
    const sub = camera.onFrame(async (frame: Frame) => {
      const base64 = await readAsBase64(frame.uri);
      decoded.set(frame.uri, base64);
      setLast(frame);
    });
    return () => sub.remove();
  }, [camera]);

  return last;
}
